package com.hrcoresystem.hrcore_api.modules.tenant.departments.application.usecase;
import com.hrcoresystem.hrcore_api.common.exception.BusinessConflictException; import com.hrcoresystem.hrcore_api.modules.tenant.departments.application.dto.DepartmentTreeResponse; import com.hrcoresystem.hrcore_api.modules.tenant.departments.domain.model.*; import com.hrcoresystem.hrcore_api.modules.tenant.departments.domain.repository.DepartmentRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class GetDepartmentTreeUseCase { private final DepartmentRepository repo; public GetDepartmentTreeUseCase(DepartmentRepository r){repo=r;} public List<DepartmentTreeResponse> execute(boolean includeInactive){List<Department> source=repo.findAllForTree(true); Map<UUID,Department> byId=new HashMap<>(); source.forEach(d->byId.put(d.id(),d)); for(Department d:source){Set<UUID> seen=new HashSet<>(); UUID c=d.id(); while(c!=null){if(!seen.add(c))throw new BusinessConflictException("La jerarquía organizacional contiene relaciones que requieren regularización"); Department current=byId.get(c); c=current==null?null:current.parentDepartmentId();} if(d.status()==DepartmentStatus.ACTIVE&&d.parentDepartmentId()!=null&&byId.get(d.parentDepartmentId())!=null&&byId.get(d.parentDepartmentId()).status()==DepartmentStatus.INACTIVE) throw new BusinessConflictException("La jerarquía organizacional contiene relaciones que requieren regularización");} List<Department> all=includeInactive?source:source.stream().filter(d->d.status()==DepartmentStatus.ACTIVE).toList(); Map<UUID,DepartmentTreeResponse> nodes=new HashMap<>(); all.forEach(d->nodes.put(d.id(),new DepartmentTreeResponse(d.id(),d.code(),d.name(),d.status(),d.parentDepartmentId(),d.managerEmployeeId(),new ArrayList<>()))); List<DepartmentTreeResponse> roots=new ArrayList<>(); for(Department d:all){DepartmentTreeResponse n=nodes.get(d.id()); if(d.parentDepartmentId()==null)roots.add(n); else {DepartmentTreeResponse p=nodes.get(d.parentDepartmentId()); if(p==null)throw new BusinessConflictException("La jerarquía organizacional contiene relaciones que requieren regularización"); ((List<DepartmentTreeResponse>)p.children()).add(n);}} Comparator<DepartmentTreeResponse> order=Comparator.comparing(DepartmentTreeResponse::name).thenComparing(DepartmentTreeResponse::code).thenComparing(DepartmentTreeResponse::id); nodes.values().forEach(n->((List<DepartmentTreeResponse>)n.children()).sort(order)); roots.sort(order); return roots;} }
